import { SessionReplayConflictError, sessionReplayErrorStatus } from "./session-recorder.js";
export function sessionReplayErrorResponse(error, status = sessionReplayErrorStatus(error)) {
    return Response.json({
        ok: false,
        error: error instanceof Error ? error.message : String(error)
    }, {
        status
    });
}
export function startSessionReplayResponse(recorder, handlers, multiplier, isCurrent = ()=>true) {
    if (!isCurrent()) {
        return sessionReplayErrorResponse(new SessionReplayConflictError("device session changed before session replay start"));
    }
    try {
        const replay = recorder.startReplay(handlers, multiplier);
        return Response.json({
            ok: true,
            session: replay.snapshot
        });
    } catch (error) {
        return sessionReplayErrorResponse(error);
    }
}
export async function stopSessionReplayResponse(recorder) {
    try {
        return Response.json({
            ok: true,
            session: await recorder.cancelAndWait()
        });
    } catch (error) {
        return sessionReplayErrorResponse(error);
    }
}
export function clearSessionReplayResponse(recorder) {
    try {
        return Response.json({
            ok: true,
            session: recorder.clear()
        });
    } catch (error) {
        return sessionReplayErrorResponse(error);
    }
}
